{
  "name": "opencode-grok-imagine-plugin",
  "version": "0.1.1",
  "description": "opencode plugin for xAI Grok Imagine image and video generation (grok-imagine-image, grok-imagine-image-quality, grok-imagine-video, grok-imagine-video-1.5-preview) via a CLIProxyAPI/OpenAI-compatible endpoint.",
  "type": "module",
  "license": "MIT",
  "author": "Lu Cao (@caoool)",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "grok",
    "grok-imagine",
    "xai",
    "image-generation",
    "video-generation",
    "text-to-image",
    "text-to-video",
    "cli-proxy-api"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/caoool/opencode-grok-imagine-plugin.git"
  },
  "homepage": "https://github.com/caoool/opencode-grok-imagine-plugin#readme",
  "bugs": {
    "url": "https://github.com/caoool/opencode-grok-imagine-plugin/issues"
  },
  "exports": {
    ".": "./src/index.js"
  },
  "main": "./src/index.js",
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.0"
  },
  "scripts": {
    "test": "node --test"
  }
}
